-- OptiMat AI: danh mục vật liệu, phương án tường, quan hệ vật liệu, tên gọi khác.
-- Sinh tự động bằng scripts/build_materials_sql.py từ data/catalog/materials_master.xlsx. Không sửa tay.
-- Chạy SAU 01_schema.sql (hoặc scripts/init_db.py). Chạy lại nhiều lần được: dòng đã có sẽ được cập nhật.
-- DBeaver: mở file này, bấm Alt+X (Execute SQL Script) để chạy toàn bộ, không bôi đen từng đoạn.

SET client_min_messages = warning;
BEGIN;

-- 1. Bổ sung cột cho bảng materials (bỏ qua nếu đã có)
ALTER TABLE "materials" ADD COLUMN IF NOT EXISTS "subgroup" VARCHAR(128);
ALTER TABLE "materials" ADD COLUMN IF NOT EXISTS "family" VARCHAR(32);
ALTER TABLE "materials" ADD COLUMN IF NOT EXISTS "usage_text" VARCHAR(255);
ALTER TABLE "materials" ADD COLUMN IF NOT EXISTS "usage_role" VARCHAR(128);
ALTER TABLE "materials" ADD COLUMN IF NOT EXISTS "tier" INTEGER;
ALTER TABLE "materials" ADD COLUMN IF NOT EXISTS "purchase_unit" VARCHAR(32);
ALTER TABLE "materials" ADD COLUMN IF NOT EXISTS "unit_conversion" FLOAT;
ALTER TABLE "materials" ADD COLUMN IF NOT EXISTS "length_mm" FLOAT;
ALTER TABLE "materials" ADD COLUMN IF NOT EXISTS "width_mm" FLOAT;
ALTER TABLE "materials" ADD COLUMN IF NOT EXISTS "height_mm" FLOAT;
ALTER TABLE "materials" ADD COLUMN IF NOT EXISTS "price_priority" VARCHAR(4);
ALTER TABLE "materials" ADD COLUMN IF NOT EXISTS "needs_lambda" BOOLEAN;
ALTER TABLE "materials" ADD COLUMN IF NOT EXISTS "lambda_source" VARCHAR(255);
ALTER TABLE "materials" ADD COLUMN IF NOT EXISTS "unit_weight_kg" FLOAT;
ALTER TABLE "materials" ADD COLUMN IF NOT EXISTS "weight_source" VARCHAR(255);
ALTER TABLE "materials" ADD COLUMN IF NOT EXISTS "transport_volume_m3" FLOAT;
ALTER TABLE "materials" ADD COLUMN IF NOT EXISTS "waste_pct" FLOAT;
ALTER TABLE "materials" ADD COLUMN IF NOT EXISTS "waste_source" VARCHAR(255);
ALTER TABLE "materials" ADD COLUMN IF NOT EXISTS "standards_text" TEXT;
ALTER TABLE "materials" ADD COLUMN IF NOT EXISTS "reference_brands" TEXT;
ALTER TABLE "materials" ADD COLUMN IF NOT EXISTS "tech_notes" TEXT;
ALTER TABLE "materials" ADD COLUMN IF NOT EXISTS "data_note" TEXT;
ALTER TABLE "materials" ADD COLUMN IF NOT EXISTS "raw_class" VARCHAR(32);

-- 2. Bảng mới (bỏ qua nếu đã có)
CREATE TABLE IF NOT EXISTS wall_systems (
	wall_system_id VARCHAR(64) NOT NULL, 
	material_id VARCHAR(64) NOT NULL, 
	wall_thickness_mm FLOAT, 
	detect_class VARCHAR(8), 
	role VARCHAR(16), 
	masonry_thickness_mm FLOAT, 
	norm_code VARCHAR(32), 
	units_per_m3 FLOAT, 
	mortar_m3_per_m3 FLOAT, 
	labor_day_per_m3 FLOAT, 
	unit_factor FLOAT, 
	mortar_material_id VARCHAR(64), 
	mortar_density FLOAT, 
	r0_reference FLOAT, 
	norm_source VARCHAR(255), 
	note TEXT, 
	data_kind VARCHAR(16) DEFAULT 'ACTUAL' NOT NULL, 
	PRIMARY KEY (wall_system_id), 
	CONSTRAINT ck_wall_systems_data_kind CHECK (data_kind IN ('ACTUAL', 'SAMPLE', 'SYNTHETIC')), 
	FOREIGN KEY(material_id) REFERENCES materials (material_id) ON DELETE CASCADE, 
	FOREIGN KEY(mortar_material_id) REFERENCES materials (material_id)
);
CREATE INDEX IF NOT EXISTS "ix_wall_systems_material_id" ON "wall_systems" ("material_id");

CREATE TABLE IF NOT EXISTS material_relations (
	id SERIAL NOT NULL, 
	material_id VARCHAR(64) NOT NULL, 
	relation_type VARCHAR(16) NOT NULL, 
	related_material_id VARCHAR(64) NOT NULL, 
	quantity FLOAT, 
	quantity_unit VARCHAR(64), 
	source VARCHAR(255), 
	note TEXT, 
	PRIMARY KEY (id), 
	CONSTRAINT material_relations_material_id_related_material_id_rela_f54c UNIQUE (material_id, related_material_id, relation_type), 
	CONSTRAINT ck_material_relations_type CHECK (relation_type IN ('REQUIRES', 'COMPOSED_OF')), 
	FOREIGN KEY(material_id) REFERENCES materials (material_id) ON DELETE CASCADE, 
	FOREIGN KEY(related_material_id) REFERENCES materials (material_id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS "ix_material_relations_material_id" ON "material_relations" ("material_id");

-- 3. Năm nhóm vật liệu bắt buộc
UPDATE "material_groups" SET "sort_order" = 1, "name" = 'Vật liệu bê tông cốt thép', "description" = 'Xi măng, cốt liệu, nước, phụ gia, bê tông, cốt thép' WHERE "group_id" = 'be_tong_cot_thep';
UPDATE "material_groups" SET "sort_order" = 2, "name" = 'Vật liệu thi công phần thô', "description" = 'Gạch xây, vữa, khối xây, chống thấm, giàn giáo, cốp pha' WHERE "group_id" = 'phan_tho';
UPDATE "material_groups" SET "sort_order" = 3, "name" = 'Vật liệu hoàn thiện', "description" = 'Ốp lát, sơn, kính, thạch cao, gỗ, cửa, vật liệu hoàn thiện' WHERE "group_id" = 'hoan_thien';
UPDATE "material_groups" SET "sort_order" = 4, "name" = 'Vật liệu khác và khung pháp lý', "description" = 'Quy chuẩn, an toàn cháy, cách nhiệt, vật liệu xanh, bitum, composite, hợp quy' WHERE "group_id" = 'khac_phap_ly';
UPDATE "material_groups" SET "sort_order" = 5, "name" = 'Vật liệu kết cấu thép và bao che', "description" = 'Thép hình, thép tấm, thép ống, liên kết, chống ăn mòn, tôn, panel, xà gồ' WHERE "group_id" = 'ket_cau_thep_bao_che';

-- 3b. Họ vật liệu: 10 dòng (nguồn data/catalog/material_families.csv)
UPDATE "material_families" SET "name" = 'Gạch đất nung đặc', "sort_order" = 1, "is_wall" = TRUE WHERE "family_id" = 'CLAY_SOLID';
UPDATE "material_families" SET "name" = 'Gạch đất nung rỗng (2 lỗ, 6 lỗ)', "sort_order" = 2, "is_wall" = TRUE WHERE "family_id" = 'CLAY_HOLLOW';
UPDATE "material_families" SET "name" = 'Gạch bê tông đặc (không nung)', "sort_order" = 3, "is_wall" = TRUE WHERE "family_id" = 'CMU_SOLID';
UPDATE "material_families" SET "name" = 'Gạch block bê tông rỗng', "sort_order" = 4, "is_wall" = TRUE WHERE "family_id" = 'CMU_HOLLOW';
UPDATE "material_families" SET "name" = 'Gạch bê tông bọt (CLC)', "sort_order" = 5, "is_wall" = TRUE WHERE "family_id" = 'CLC';
UPDATE "material_families" SET "name" = 'Gạch bê tông khí chưng áp (AAC)', "sort_order" = 6, "is_wall" = TRUE WHERE "family_id" = 'AAC';
UPDATE "material_families" SET "name" = 'Tấm tường ALC', "sort_order" = 7, "is_wall" = TRUE WHERE "family_id" = 'ALC_PANEL';
UPDATE "material_families" SET "name" = 'Tấm panel EPS 3D', "sort_order" = 8, "is_wall" = TRUE WHERE "family_id" = 'EPS_PANEL';
UPDATE "material_families" SET "name" = 'Vách tấm xi măng sợi (Cemboard)', "sort_order" = 9, "is_wall" = TRUE WHERE "family_id" = 'CEMBOARD';
UPDATE "material_families" SET "name" = 'Vách thạch cao', "sort_order" = 10, "is_wall" = TRUE WHERE "family_id" = 'GYPSUM';

